(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-536":{scenario:{company:"Tân Hưng Precision Parts",supervisor:{name:"Đặng Quốc Bảo",role:{vi:"Trưởng phòng Đảm bảo Chất lượng",en:"Quality Assurance Manager"}},ref_code:"PPAP-4471",title:{vi:"Đúng đặc tính. Đúng Cpk. Đúng dữ liệu thật.",en:"Right characteristic. Right Cpk. Real data only."},brief:{vi:"Bạn hoàn thiện hồ sơ PPAP-4471 cho giá đỡ kẹp phanh. Đặc tính D-04 là đường kính lỗ bắt bulông 12.00 ± 0.05 mm; DFMEA ghi mức nghiêm trọng S = 10. Dữ liệu SPC 125 mẫu: trung bình 12.022 mm, độ lệch chuẩn trong nhóm 0.008 mm. Bản nháp xếp D-04 là đặc tính thường và báo Cpk 2.08. Dùng terminal để chẩn đoán, sửa phân loại đặc tính và chỉ số Cpk, rồi lập báo cáo có căn cứ.",en:"You are completing PPAP-4471 for a brake caliper bracket. Characteristic D-04 is the bolt hole diameter 12.00 ± 0.05 mm; the DFMEA rates severity S = 10. SPC data from 125 samples: mean 12.022 mm, within-subgroup standard deviation 0.008 mm. The draft lists D-04 as a standard characteristic and reports Cpk 2.08. Use the terminal to diagnose, correct the characteristic class and the Cpk, then write an evidence-based report."},reference_title:{vi:"DFMEA, kế hoạch kiểm soát & yêu cầu khách hàng đã duyệt · PPAP-4471",en:"Approved DFMEA, control plan & customer requirements · PPAP-4471"},fields:[{id:"CHAR_CLASS",label:{vi:"Phân loại đặc tính D-04",en:"Characteristic class D-04"},initial:"STD",expected:"CC-SAFETY",choices:["STD","SC-FUNCTION","CC-SAFETY"],reference:"Ma trận đặc tính đặc biệt (CSR)",hint:{vi:"Mức nghiêm trọng 9-10 trong DFMEA nghĩa là ảnh hưởng an toàn hoặc pháp quy.",en:"A DFMEA severity of 9-10 means a safety or regulatory effect."}},{id:"CPK",label:{vi:"Chỉ số năng lực quá trình Cpk",en:"Process capability index Cpk"},initial:"2.08",expected:"1.17",reference:"Báo cáo năng lực quá trình D-04",ref_value:{vi:"USL 12.05; LSL 11.95; trung bình 12.022; sigma trong nhóm 0.008 (mm)",en:"USL 12.05; LSL 11.95; mean 12.022; within sigma 0.008 (mm)"},hint:{vi:"Cpk lấy phía gần giới hạn dung sai hơn; độ rộng dung sai chia 6 sigma chỉ là Cp.",en:"Cpk uses the side closer to a limit; tolerance width over 6 sigma is only Cp."}}],sop32:{vi:"Cpk = min(USL - trung bình, trung bình - LSL) / (3 x sigma trong nhóm), làm tròn 2 chữ số thập phân; đặc tính an toàn yêu cầu Cpk ≥ 1.67, không đạt thì kiểm tra 100% và lập kế hoạch cải tiến.",en:"Cpk = min(USL - mean, mean - LSL) / (3 x within sigma), rounded to 2 decimals; safety characteristics need Cpk ≥ 1.67, otherwise apply 100% inspection and an improvement plan."},context:{label:"QMS / PPAP-4471",metrics:[{label:{vi:"Dung sai D-04",en:"D-04 tolerance"},value:"12.00 ± 0.05 mm"},{label:{vi:"Trung bình mẫu",en:"Sample mean"},value:"12.022 mm"},{label:{vi:"Sigma trong nhóm",en:"Within sigma"},value:"0.008 mm"},{label:{vi:"Mức nghiêm trọng DFMEA",en:"DFMEA severity"},value:"S = 10"}]},crisis:{vi:"Trưởng xưởng nhắn: “Xóa bớt mấy điểm đo lệch trong file SPC cho Cpk lên 1.67 rồi nộp PPAP luôn. Khách hàng đang giục, lô thử LOT-2611 phải xuất trong tuần này.”",en:"The workshop manager messages: “Delete a few off-center readings in the SPC file so Cpk reaches 1.67, then submit the PPAP. The customer is pushing and trial lot LOT-2611 must ship this week.”"},options:{safe:{vi:"Từ chối sửa dữ liệu, giữ lô LOT-2611 ở trạng thái HOLD, báo Trưởng phòng QA, áp dụng kiểm tra 100% và nộp dữ liệu thật kèm kế hoạch hành động hoặc xin khách hàng chấp thuận sai lệch tạm thời.",en:"Refuse to alter data, keep LOT-2611 on HOLD, inform the QA Manager, apply 100% inspection and submit real data with an action plan or request a temporary customer deviation."},shortcut:{vi:"Lọc bớt điểm đo lệch cho đạt Cpk 1.67 và xuất lô đúng hẹn.",en:"Filter out the off-center readings to reach Cpk 1.67 and ship on time."},wait:{vi:"Để hồ sơ nằm đó, chờ khách hàng tự phát hiện rồi tính.",en:"Leave the file as is and wait for the customer to notice."}},questions:{vi:["Vì sao D-04 phải là CC-SAFETY? Dữ liệu DFMEA và yêu cầu riêng của khách hàng nào chứng minh?","Trình bày cách tính Cpk, vì sao Cp không phản ánh độ lệch tâm và hành động ngăn chặn khi Cpk dưới ngưỡng yêu cầu."],en:["Why must D-04 be CC-SAFETY? Which DFMEA data and customer-specific requirement prove it?","Explain how you calculated Cpk, why Cp ignores centering, and the containment actions when Cpk is below the requirement."]},hints:{vi:["Chạy cat dfmea.txt và cat csr.txt để đối chiếu mức nghiêm trọng với ma trận phân loại.","Dùng dữ liệu spc d-04, tính hai phía tới USL và LSL rồi lấy giá trị nhỏ hơn theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu chất lượng không được chỉnh sửa; mọi áp lực xuất hàng phải được báo cáo."],en:["Run cat dfmea.txt and cat csr.txt to match the severity against the classification matrix.","Use the spc d-04 data, compute both sides to USL and LSL and take the smaller one per SOP 3.2.","Re-read SOP 4.2: quality data must never be edited; any pressure to ship must be escalated."]},terminal:{system:"qms-ctl",settable:["CHAR_CLASS","CPK"],commands:[{cmd:"status",out:{vi:"PPAP-4471: trạng thái nháp; lô thử LOT-2611 đang HOLD; 2 trường chờ kỹ sư QA xác nhận",en:"PPAP-4471: draft status; trial lot LOT-2611 on HOLD; 2 fields awaiting QA engineer sign-off"}},{cmd:"cat dfmea.txt",out:{vi:"D-04 đường kính lỗ bắt bulông kẹp phanh: lỗi lắp lỏng gây mất lực kẹp phanh; S = 10, O = 3, D = 4",en:"D-04 caliper bolt hole diameter: loose fit causes loss of brake clamping force; S = 10, O = 3, D = 4"}},{cmd:"cat csr.txt",out:{vi:"Yêu cầu riêng khách hàng: S 9-10 là CC-SAFETY, Cpk ≥ 1.67; S 5-8 là SC-FUNCTION, Cpk ≥ 1.33; còn lại STD",en:"Customer-specific requirement: S 9-10 is CC-SAFETY, Cpk ≥ 1.67; S 5-8 is SC-FUNCTION, Cpk ≥ 1.33; others STD"}},{cmd:"spc d-04",out:{vi:"n = 125 (25 nhóm x 5); trung bình 12.022 mm; sigma trong nhóm 0.008 mm; USL 12.05; LSL 11.95; quá trình ổn định",en:"n = 125 (25 subgroups x 5); mean 12.022 mm; within sigma 0.008 mm; USL 12.05; LSL 11.95; process in control"}},{cmd:"msa d-04",out:{vi:"Gauge R&R: %GRR = 8.4%, ndc = 9; hệ thống đo chấp nhận được",en:"Gauge R&R: %GRR = 8.4%, ndc = 9; measurement system acceptable"}}]}},learning:{summary:{vi:"Kỹ sư Quản lý Chất lượng Nhà máy xây dựng và duy trì hệ thống quản lý chất lượng theo ISO 9001 và IATF 16949: lập kế hoạch kiểm soát, phân tích năng lực quá trình, đánh giá hệ thống đo, phê duyệt sản phẩm (PPAP), xử lý sản phẩm không phù hợp và khiếu nại khách hàng bằng phương pháp giải quyết vấn đề có cấu trúc. Nghề bảo vệ an toàn người dùng và uy tín doanh nghiệp, đòi hỏi tư duy thống kê và sự trung thực tuyệt đối với dữ liệu.",en:"A Manufacturing QA/QC Engineer builds and maintains the quality management system under ISO 9001 and IATF 16949: control plans, process capability analysis, measurement system analysis, production part approval (PPAP), nonconforming product handling and customer complaints through structured problem solving. The role protects end-user safety and company reputation and requires statistical thinking and absolute honesty with data."},responsibilities:{vi:["Lập và cập nhật kế hoạch kiểm soát, hướng dẫn kiểm tra cho từng đặc tính sản phẩm.","Phân tích SPC, năng lực quá trình (Cp, Cpk, Ppk) và đánh giá hệ thống đo (MSA).","Chuẩn bị, nộp hồ sơ PPAP và quản lý thay đổi sản phẩm, quá trình.","Xử lý sản phẩm không phù hợp, khiếu nại khách hàng bằng 8D và phân tích nguyên nhân gốc.","Đánh giá nội bộ, đánh giá nhà cung cấp và duy trì chứng nhận IATF 16949."],en:["Create and update control plans and inspection instructions for each product characteristic.","Analyze SPC, process capability (Cp, Cpk, Ppk) and run measurement system analysis (MSA).","Prepare and submit PPAP files and manage product and process changes.","Handle nonconforming product and customer complaints with 8D and root cause analysis.","Run internal and supplier audits and maintain IATF 16949 certification."]},competencies:[{name:{vi:"Công cụ lõi ô tô",en:"Automotive core tools"},desc:{vi:"Vận dụng APQP, FMEA, MSA, SPC, PPAP nhất quán từ thiết kế tới sản xuất loạt.",en:"Apply APQP, FMEA, MSA, SPC and PPAP consistently from design to mass production."}},{name:{vi:"Thống kê chất lượng",en:"Quality statistics"},desc:{vi:"Đọc biểu đồ kiểm soát, tính năng lực quá trình và chọn phương án lấy mẫu phù hợp.",en:"Read control charts, compute process capability and choose suitable sampling plans."}},{name:{vi:"Giải quyết vấn đề",en:"Problem solving"},desc:{vi:"Dùng 8D, 5 Why, Ishikawa để tìm nguyên nhân gốc và khóa hành động khắc phục.",en:"Use 8D, 5 Why and Ishikawa to find root causes and lock in corrective actions."}},{name:{vi:"Đánh giá hệ thống",en:"System auditing"},desc:{vi:"Đánh giá quá trình, sản phẩm, nhà cung cấp theo tiêu chuẩn và yêu cầu riêng của khách hàng.",en:"Audit processes, products and suppliers against standards and customer-specific requirements."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Không chỉnh sửa dữ liệu đo, giữ hàng nghi ngờ và báo cáo trung thực khi chưa đạt yêu cầu.",en:"Never edit measurement data, hold suspect product and report honestly when requirements are not met."}}],knowledge:{vi:["ISO 9001:2015 - yêu cầu hệ thống quản lý chất lượng.","IATF 16949:2016 - yêu cầu hệ thống quản lý chất lượng ngành ô tô, áp dụng cùng ISO 9001.","Bộ công cụ lõi AIAG: APQP, PPAP, MSA, SPC và Sổ tay FMEA AIAG & VDA (2019).","ISO 2859-1 - quy trình lấy mẫu kiểm tra định tính theo AQL.","Năng lực quá trình: Cp, Cpk, Pp, Ppk và ngưỡng chấp nhận theo yêu cầu khách hàng.","Phương pháp 8D, 5 Why, biểu đồ Ishikawa và kiểm soát thay đổi."],en:["ISO 9001:2015 - quality management system requirements.","IATF 16949:2016 - automotive quality management system requirements, used together with ISO 9001.","AIAG core tools: APQP, PPAP, MSA, SPC and the AIAG & VDA FMEA Handbook (2019).","ISO 2859-1 - sampling procedures for inspection by attributes using AQL.","Process capability: Cp, Cpk, Pp, Ppk and acceptance thresholds set by the customer.","8D, 5 Why, Ishikawa diagrams and change control."]},tools:["Phần mềm SPC","Máy đo tọa độ CMM","Phần mềm thống kê (Minitab hoặc tương đương)","Hệ thống QMS điện tử","Thước đo, calip, đồng hồ so đã hiệu chuẩn"],kpis:{vi:["Số lỗi lọt tới khách hàng tính theo PPM.","Tỷ lệ hồ sơ PPAP được duyệt ngay lần nộp đầu.","Tỷ lệ đặc tính đặc biệt đạt yêu cầu Cpk.","Thời gian đóng báo cáo 8D khiếu nại khách hàng."],en:["Defects escaping to the customer in PPM.","Share of PPAP files approved at first submission.","Share of special characteristics meeting the Cpk requirement.","Time to close customer complaint 8D reports."]},day:[{time:"07:45",vi:"Họp chất lượng đầu ca, rà lỗi ca trước và các lô đang giữ HOLD.",en:"Attend the start-of-shift quality meeting and review last shift's defects and held lots."},{time:"09:00",vi:"Phân tích biểu đồ SPC, tính năng lực quá trình cho các đặc tính đặc biệt.",en:"Analyze SPC charts and compute capability for special characteristics."},{time:"11:00",vi:"Đánh giá hệ thống đo mới, chạy nghiên cứu Gauge R&R với 3 người đo.",en:"Assess a new gauge and run a Gauge R&R study with 3 appraisers."},{time:"14:00",vi:"Họp nhóm 8D xử lý khiếu nại, xác nhận nguyên nhân gốc và hành động khắc phục.",en:"Lead an 8D team on a complaint, confirming root cause and corrective actions."},{time:"16:30",vi:"Hoàn thiện hồ sơ PPAP và cập nhật kế hoạch kiểm soát.",en:"Finalize the PPAP file and update the control plan."}],mistakes:{vi:["Báo cáo Cp thay cho Cpk, bỏ qua việc quá trình bị lệch tâm.","Xếp đặc tính ảnh hưởng an toàn vào loại thường, làm thiếu kiểm soát và tần suất đo.","Xóa điểm đo bất lợi hoặc xuất hàng nghi ngờ để kịp tiến độ."],en:["Reporting Cp instead of Cpk and ignoring an off-center process.","Classifying a safety characteristic as standard, leaving controls and measurement frequency too weak.","Deleting unfavorable readings or shipping suspect product to meet a deadline."]},career:[{vi:"Kỹ thuật viên kiểm tra chất lượng (QC)",en:"Quality control technician"},{vi:"Kỹ sư chất lượng (QA/QC)",en:"QA/QC engineer"},{vi:"Trưởng nhóm chất lượng khách hàng, nhà cung cấp",en:"Customer and supplier quality lead"},{vi:"Trưởng phòng Đảm bảo Chất lượng nhà máy",en:"Plant quality manager"}],glossary:[{term:"Cpk",vi:"Chỉ số năng lực quá trình có xét độ lệch tâm: khoảng cách nhỏ nhất tới giới hạn chia 3 sigma.",en:"Process capability index that accounts for centering: the smaller distance to a limit divided by 3 sigma."},{term:"PPAP",vi:"Quy trình phê duyệt chi tiết sản xuất, chứng minh quá trình sản xuất đáp ứng mọi yêu cầu của khách hàng.",en:"Production Part Approval Process proving the production process meets all customer requirements."},{term:"Đặc tính đặc biệt",vi:"Đặc tính sản phẩm, quá trình ảnh hưởng an toàn, pháp quy hoặc chức năng, cần kiểm soát tăng cường.",en:"Special characteristic: a product or process feature affecting safety, regulation or function that needs extra control."},{term:"MSA",vi:"Phân tích hệ thống đo, đánh giá độ lặp lại, độ tái lập và độ chính xác của phép đo.",en:"Measurement system analysis assessing repeatability, reproducibility and accuracy."},{term:"8D",vi:"Phương pháp giải quyết vấn đề 8 bước từ lập nhóm, ngăn chặn, tìm nguyên nhân gốc tới phòng ngừa tái diễn.",en:"An 8-step problem-solving method from team setup and containment to root cause and recurrence prevention."}],quiz:[{q:{vi:"USL 10.10, LSL 9.90, trung bình 10.04, sigma 0.02. Cpk bằng bao nhiêu?",en:"USL 10.10, LSL 9.90, mean 10.04, sigma 0.02. What is Cpk?"},options:{vi:["1.67","1.00","2.33","0.67"],en:["1.67","1.00","2.33","0.67"]},answer:1,explain:{vi:"min(10.10 - 10.04, 10.04 - 9.90) / (3 x 0.02) = 0.06 / 0.06 = 1.00; còn 1.67 là Cp.",en:"min(10.10 - 10.04, 10.04 - 9.90) / (3 x 0.02) = 0.06 / 0.06 = 1.00; 1.67 is Cp."}},{q:{vi:"Nghiên cứu Gauge R&R cho %GRR = 34%. Theo hướng dẫn MSA phổ biến, kết luận nào đúng?",en:"A Gauge R&R study gives %GRR = 34%. Under common MSA guidance, which conclusion is right?"},options:{vi:["Chấp nhận được","Có thể chấp nhận tùy ứng dụng","Không chấp nhận, phải cải tiến hệ thống đo","Không cần đánh giá thêm"],en:["Acceptable","May be acceptable depending on use","Unacceptable, improve the measurement system","No further assessment needed"]},answer:2,explain:{vi:"Dưới 10% là chấp nhận, 10-30% có thể chấp nhận có điều kiện, trên 30% là không chấp nhận.",en:"Under 10% is acceptable, 10-30% conditionally acceptable, above 30% unacceptable."}},{q:{vi:"Cấp trên yêu cầu xóa vài điểm đo xấu để hồ sơ PPAP đạt chỉ tiêu. Bạn làm gì?",en:"Your manager asks you to delete a few bad readings so the PPAP meets target. What do you do?"},options:{vi:["Từ chối, giữ dữ liệu gốc, giữ hàng và báo Trưởng phòng QA","Xóa vì chỉ là vài điểm ngoại lệ","Đo lại đến khi đạt rồi bỏ số cũ","Nộp hồ sơ nhưng không ký tên"],en:["Refuse, keep raw data, hold product and inform the QA Manager","Delete them since they are just outliers","Re-measure until it passes and drop old values","Submit the file without signing"]},answer:0,explain:{vi:"Làm sai lệch dữ liệu chất lượng có thể gây mất an toàn và vi phạm nghiêm trọng yêu cầu khách hàng.",en:"Falsifying quality data can endanger users and seriously breach customer requirements."}},{q:{vi:"IATF 16949 được áp dụng cùng với tiêu chuẩn nào?",en:"IATF 16949 is used together with which standard?"},options:{vi:["ISO 14001","ISO 45001","ISO/IEC 27001","ISO 9001"],en:["ISO 14001","ISO 45001","ISO/IEC 27001","ISO 9001"]},answer:3,explain:{vi:"IATF 16949 bổ sung yêu cầu ngành ô tô và phải áp dụng cùng ISO 9001:2015.",en:"IATF 16949 adds automotive requirements and must be applied with ISO 9001:2015."}}],tools_en:["SPC software","Coordinate measuring machine (CMM)","Statistical software (Minitab or equivalent)","Electronic quality management system (eQMS)","Calibrated gauges, calipers & dial indicators"]}}})})(window.KKR);
